+func worktreeDirty(ctx context.Context, runner CommandRunner, repoDir string) bool {
+	stdout, _, err := runner.Run(ctx, repoDir, "git", "status", "--porcelain")
+	return err == nil && strings.TrimSpace(string(stdout)) != ""
